(()=>{
 const C=MatchaCore,copy=x=>JSON.parse(JSON.stringify(x)),id=()=> 'matcha-'+crypto.randomUUID();let rows=[],sync={ready:false},cloud,account=null,editId=null,mode='drink',tinEditing=null,opening=false,baseline=null;
 const nav=document.createElement('button');nav.dataset.page='matcha';nav.textContent='抹茶日誌';document.querySelector('nav').append(nav);
 const css=document.createElement('link');css.rel='stylesheet';css.href='matcha.css';document.head.append(css);
 const dialog=document.createElement('dialog');dialog.id='matcha-editor';document.body.append(dialog);
 const num=(name,label,value,min=0,max=3000)=>`<label>${label}<input name="${name}" type="number" step="0.1" min="${min}" max="${max}" value="${value}" required></label>`;
 const select=(name,label,values)=>`<label>${label}<select name="${name}">${values.map(x=>`<option>${x}</option>`).join('')}</select></label>`;
 const rate=(name,label)=>`<label>${label}<select name="${name}"><option value="">未評分</option>${[1,2,3,4,5].map(x=>`<option value="${x}">${x} / 5</option>`).join('')}</select></label>`;
 dialog.innerHTML=`<form id="matcha-form"><div class="dialog-head"><h2 id="matcha-title">記低一杯抹茶</h2><button type="button" data-matcha-close>✕</button></div><label>抹茶名稱<input name="title" required maxlength="160"></label><label>選擇抹茶罐／批次<select name="tinId"><option value="">未連結抹茶罐</option></select></label><label data-matcha-observed>日期與時間<input name="date" type="datetime-local" required></label>${select('style','飲品類型',['純抹茶','熱 Latte','凍 Latte'])}<div class="fields">${num('powder','抹茶粉 g',3,.1,100)}${num('water','打茶用水 g',40,.1)}${num('temp','打茶水溫 °C',80,1,100)}${num('milk','奶量 ml',150)}${num('ice','冰量 g',0)}${num('sweetener','糖／糖漿用量 g',0,0,500)}</div><div class="fields">${select('milkType','奶種類',['牛奶','燕麥奶','豆奶','其他','不加奶'])}${select('sweetenerType','甜味材料',['不加糖','砂糖','糖漿','蜜糖','其他'])}${select('tool','打茶工具',['竹筅','電動打奶器','其他'])}${num('whiskSeconds','打茶時間 秒',30,0,3600)}</div><label><input name="sifted" type="checkbox"> 已篩粉</label><label><input name="paste" type="checkbox"> 先調成茶膏</label><section class="matcha-tools"><h3>配方份量換算</h3><div class="fields"><label>放大倍數<input id="matcha-factor" type="number" min="0.1" max="20" step="0.1" value="2"></label><label>換算方式<select id="matcha-scale-mode"><option value="all">整體放大份量</option><option value="milk">奶量不變、調整茶濃度</option></select></label></div><button type="button" data-matcha-scale>套用換算</button><output id="matcha-ratio"></output><div class="fields">${num('hotTemp','熱水溫度 °C',100,1,100)}${num('roomTemp','室溫水溫度 °C',25,0,100)}</div><div id="matcha-mix" aria-live="polite"></div><p class="hint">溝水只計打茶用水，唔代表加奶後成品溫度。</p></section><details data-matcha-observed><summary>抹茶評分與口感</summary><div class="fields">${rate('rating','整體滿意度')}${rate('strength','茶味濃度')}${rate('bitterness','苦澀感')}${rate('sweetness','甜度')}${rate('smoothness','順滑度')}${rate('clumps','粉粒感')}${rate('milkBalance','奶味蓋過茶味')}</div><p class="hint">強度評分：1 低、5 高；整體滿意度：1 不喜歡、5 好鍾意。</p></details><label>筆記<textarea name="notes" rows="2"></textarea></label><p id="matcha-draft-status" role="status"></p><div class="form-bottom"><button type="button" data-matcha-resume>還原抹茶草稿</button><button type="submit" class="primary">儲存抹茶</button></div></form>`;
 const f=dialog.querySelector('form');
 const tins=()=>rows.filter(r=>r.kind==='tin'),drinks=()=>rows.filter(r=>r.kind==='drink'),recipes=()=>rows.filter(r=>r.kind==='recipe');
 const draftKey=()=> 'slowbrew-matcha-draft-v1:'+account;
 function getValues(){const data=Object.fromEntries(new FormData(f));for(const k of ['powder','water','temp','milk','ice','sweetener','whiskSeconds'])data[k]=Number(f.elements[k].value);data.sifted=f.elements.sifted.checked;data.paste=f.elements.paste.checked;return data}
 function draft(){if(!account||opening||!dialog.open||mode!=='drink')return;try{localStorage.setItem(draftKey(),JSON.stringify({values:getValues(),editId}));$('#matcha-draft-status').textContent='抹茶草稿已存喺此裝置'}catch{$('#matcha-draft-status').textContent='未能保存抹茶草稿，請保留此畫面。'}}
 function update(){const r=getValues();f.elements.milk.closest('label').hidden=r.style==='純抹茶';f.elements.milk.disabled=r.style==='純抹茶';f.elements.milkType.closest('label').hidden=r.style==='純抹茶';f.elements.ice.closest('label').hidden=r.style!=='凍 Latte';f.elements.ice.disabled=r.style!=='凍 Latte';$('#matcha-ratio').innerHTML=`<span>粉：水：奶</span> = ${r.powder}g：${r.water}g：${r.style==='純抹茶'?0:r.milk}ml`;try{const m=calculateWaterMix({mass:r.water,target:r.temp,hot:Number(f.elements.hotTemp.value),room:Number(f.elements.roomTemp.value)});$('#matcha-mix').textContent=`${f.elements.hotTemp.value}°C 熱水 ${m.hotGrams}g ＋ ${f.elements.roomTemp.value}°C 室溫水 ${m.roomGrams}g`}catch(e){$('#matcha-mix').textContent=e.message}}
 function open(r=null,kind='drink',editingRow=false){opening=true;try{mode=kind;editId=editingRow?r?.id:null;f.reset();f.elements.date.disabled=kind==='recipe';f.elements.tinId.innerHTML='<option value="">未連結抹茶罐</option>'+tins().map(t=>`<option translate="no" value="${esc(t.id)}">${esc(t.title)}</option>`).join('');f.elements.date.value=localTime();if(r)for(const [k,v]of Object.entries(r))if(f.elements[k]){if(f.elements[k].type==='checkbox')f.elements[k].checked=!!v;else f.elements[k].value=v??''}if(!editingRow)f.elements.date.value=localTime();$('#matcha-title').textContent=kind==='recipe'?'抹茶食譜':'記低一杯抹茶';f.querySelectorAll('[data-matcha-observed]').forEach(e=>e.hidden=kind==='recipe');$('#matcha-draft-status').textContent='';update();dialog.showModal()}finally{opening=false}}
 f.addEventListener('input',()=>{update();draft()});f.addEventListener('change',()=>{update();draft()});f.elements.tinId.onchange=()=>{const t=tins().find(t=>t.id===f.elements.tinId.value);if(t)f.elements.title.value=t.title;draft()};
 f.onsubmit=e=>{e.preventDefault();if(!sync.ready){toast('請等抹茶帳戶狀態確認。');return}if(!f.reportValidity())return;try{let r=getValues();if(r.style==='純抹茶'){r.milk=0;r.milkType='不加奶'}if(r.style!=='凍 Latte')r.ice=0;C.validate(r);r={...r,id:editId||id(),kind:mode};if(mode==='recipe'){r=C.recipe(r,r.id);r.notes=getValues().notes}if(cloud.save(r)){if(mode==='drink'&&account)localStorage.removeItem(draftKey());dialog.close();render()}}catch(error){toast(error.message)}};
 f.addEventListener('click',e=>{if(e.target.closest('[data-matcha-close]')){draft();dialog.close()}if(e.target.closest('[data-matcha-scale]')){try{const r=C.scale(getValues(),Number($('#matcha-factor').value),$('#matcha-scale-mode').value==='milk');for(const k of ['powder','water','milk','ice','sweetener'])f.elements[k].value=r[k];update();draft()}catch(error){toast(error.message)}}if(e.target.closest('[data-matcha-resume]')){try{const d=JSON.parse(localStorage.getItem(draftKey()));if(d){if(d.editId&&!drinks().some(r=>r.id===d.editId)){toast('原紀錄已不存在，未有還原草稿。');return}open({...d.values,id:d.editId},'drink',!!d.editId)}}catch{toast('未能讀取抹茶草稿。')}}});
 dialog.addEventListener('cancel',draft);window.addEventListener('pagehide',draft);
 const tinDialog=document.createElement('dialog');tinDialog.id='matcha-tin';tinDialog.innerHTML=`<form><div class="dialog-head"><h2>抹茶粉資料</h2><button type="button" data-tin-close>✕</button></div><label>抹茶名稱<input name="title" required maxlength="160"></label><label>品牌<input name="brand"></label><label>批次<input name="batch"></label><label>開封日期<input name="opened" type="date"></label>${num('weight','起始重量 g',30,0,10000)}<div class="form-bottom"><button class="primary">儲存抹茶粉</button></div></form>`;document.body.append(tinDialog);
 tinDialog.querySelector('[data-tin-close]').onclick=()=>tinDialog.close();tinDialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(!sync.ready)return;const data=Object.fromEntries(new FormData(e.target));if(cloud.save({...data,weight:Number(data.weight),kind:'tin',id:tinEditing||id()}))tinDialog.close()};
 function showTin(r){tinEditing=r?.id||null;const tf=tinDialog.querySelector('form');tf.reset();if(r)for(const [k,v]of Object.entries(r))if(tf.elements[k])tf.elements[k].value=v;tinDialog.showModal()}
 function draw(){if(page!=='matcha')return;$('#content').innerHTML=`<div class="page-title"><h1>抹茶日誌</h1><button type="button" class="primary" data-m-new>記錄抹茶</button></div><div class="matcha-sync" role="status">${esc(sync.error||(sync.ready?(sync.user?(sync.pending?'抹茶等待同步':sync.serverSeen?'抹茶已同步':'正在讀取抹茶伺服器'):'抹茶只存本機'):'正在讀取抹茶帳戶…'))}${sync.user&&!sync.serverSeen&&!sync.error?' · 正在讀取伺服器':''}<button type="button" data-m-retry>重試</button>${sync.hasLocal?'<button type="button" data-m-import>匯入本機抹茶紀錄</button>':''}</div><div class="history-actions"><button data-m-new-recipe>新增抹茶食譜</button><button data-m-tin>新增抹茶粉</button><button data-m-draft>繼續抹茶草稿</button><button data-m-export>匯出抹茶資料</button></div><h2>抹茶粉庫存</h2><div class="grid">${tins().map(t=>`<article class="card"><h3 translate="no">${esc(t.title)}</h3><p translate="no">${esc([t.brand,t.batch,t.opened].filter(Boolean).join(' · '))}</p><p>${C.remaining(t,rows)==null?'未設定庫存':C.remaining(t,rows)+'g 剩餘'}</p><button data-m-tin-edit="${esc(t.id)}">修改抹茶粉</button></article>`).join('')||'<p>新增抹茶粉後，可連結每杯用量。</p>'}</div><h2>抹茶食譜</h2><div class="grid">${recipes().map(r=>`<article class="card"><h3 translate="no">${esc(r.title)}</h3><p>${esc(r.style)} · ${r.powder}g / ${r.water}g / ${r.milk}ml</p><button data-m-use="${r.id}">用呢份抹茶食譜</button><button data-m-recipe-edit="${r.id}">修改抹茶食譜</button></article>`).join('')||'<p>收藏自己最滿意嘅抹茶配方。</p>'}</div><h2>抹茶記錄</h2><div class="grid">${drinks().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(r=>`<article class="card"><h3 translate="no">${esc(r.title)}</h3><p>${esc(r.date||'')} · ${esc(r.style)}</p><p>${r.powder}g 粉 · ${r.water}g 水 · ${r.milk}ml 奶<br>${r.temp}°C · ${r.whiskSeconds} 秒 · ${r.rating||'—'}/5</p><p translate="no">${esc(r.notes||'')}</p><div class="history-actions"><button data-m-edit="${r.id}">修改抹茶記錄</button><button data-m-again="${r.id}">再整一杯</button><button data-m-save-recipe="${r.id}">收藏抹茶食譜</button><button data-m-compare="${r.id}">比較抹茶</button><button data-m-delete="${r.id}">刪除抹茶記錄</button></div></article>`).join('')||'<p>未有抹茶記錄。</p>'}</div>`}
 const prevRender=render;render=function(){prevRender();draw()};
 const confirmDialog=document.createElement('dialog');confirmDialog.innerHTML='<form method="dialog"><h2>刪除抹茶記錄？</h2><p>已連結抹茶粉嘅用量會加返庫存。</p><button value="cancel">取消</button><button value="delete">刪除</button></form>';document.body.append(confirmDialog);let removing=null;confirmDialog.onclose=()=>{if(confirmDialog.returnValue==='delete'&&removing)cloud.save({id:removing,_deleted:true,date:localTime()});removing=null};
 const compare=document.createElement('dialog');compare.id='matcha-compare';document.body.append(compare);
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const find=v=>rows.find(r=>r.id===v);
 if(b.hasAttribute('data-m-new'))open();if(b.hasAttribute('data-m-new-recipe'))open(null,'recipe');if(b.hasAttribute('data-m-tin'))showTin();if(b.dataset.mTinEdit)showTin(find(b.dataset.mTinEdit));
 if(b.dataset.mEdit)open(find(b.dataset.mEdit),'drink',true);if(b.dataset.mRecipeEdit)open(find(b.dataset.mRecipeEdit),'recipe',true);if(b.dataset.mUse||b.dataset.mAgain)open(C.rebrew(find(b.dataset.mUse||b.dataset.mAgain)));
 if(b.dataset.mSaveRecipe)cloud.save(C.recipe(find(b.dataset.mSaveRecipe),id()));if(b.dataset.mDelete){removing=b.dataset.mDelete;confirmDialog.returnValue='';confirmDialog.showModal()}
 if(b.hasAttribute('data-m-draft')){open();f.querySelector('[data-matcha-resume]').click()}if(b.hasAttribute('data-m-retry'))cloud?.retry();if(b.hasAttribute('data-m-import'))cloud?.importLocal();
 if(b.dataset.mCompare){const r=find(b.dataset.mCompare),others=drinks().filter(x=>x.id!==r.id&&(r.tinId?x.tinId===r.tinId:x.title===r.title));baseline=others.find(x=>String(x.date)<String(r.date));compare.innerHTML='<h2>比較抹茶</h2>'+(baseline?`<p>較早一杯／今次</p><table>${C.compare(baseline,r).map(x=>`<tr><th>${esc({powder:'抹茶粉 g',water:'打茶用水 g',milk:'奶量 ml',temp:'水溫 °C',whiskSeconds:'打茶時間 秒',rating:'整體滿意度'}[x.key])}</th><td>${esc(x.before)}</td><td>${esc(x.after)}</td></tr>`).join('')}</table>`:'<p>未有同款抹茶嘅較早記錄。</p>')+'<button type="button" data-m-compare-close>關閉</button>';compare.showModal()}
 if(b.hasAttribute('data-m-compare-close'))compare.close();if(b.hasAttribute('data-m-export')){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,matcha:rows},null,2)],{type:'application/json'}));a.download='matcha-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 });
 // Coffee retains its own form, data, counters and stock. This entry changes only the visible page.
 const jump=document.createElement('button');jump.type='button';jump.textContent='改為記錄抹茶';jump.onclick=()=>{window.coffeeBeforeAccountChange?.();$('#editor').close();page='matcha';render();open()};form.querySelector('.dialog-head').after(jump);
 import('./matcha-cloud.mjs').then(async m=>{cloud=await m.connectMatcha(r=>{rows=r;draw()},s=>{sync=s;draw()},uid=>{draft();dialog.close();tinDialog.close();compare.close();confirmDialog.close();account=uid})}).catch(()=>{sync={ready:false,error:'未能啟動抹茶同步，請重新整理。'};draw()});
})();
